const profile = $('Fetch Brand Profile').first().json;
const stylePrompt = profile.style_prompt || '';

const requestBody = JSON.stringify({
  model: 'gpt-4o-mini',
  messages: [
    {
      role: 'system',
      content: 'You are a brand designer. Analyze the brand guidelines and extract the color palette and visual style. Return ONLY a valid JSON object with these exact keys: primaryColor (main brand color hex), secondaryColor (secondary hex), accentColor (accent hex), backgroundColor (clean background hex, usually white or near-white), textColor (body text hex, usually dark), visualTheme (a short description of the visual style for AI image generation, e.g. clean minimalist corporate blue tones professional photography). No markdown, no code fences, just the JSON object.'
    },
    {
      role: 'user',
      content: 'Brand guidelines: ' + stylePrompt
    }
  ],
  response_format: { type: 'json_object' }
});

return [{ json: { requestBody } }];

const raw = $('Analyze Brand Colors').first().json;
let colors;
try {
  const text = raw.choices?.[0]?.message?.content || '{}';
  colors = JSON.parse(text);
} catch(e) {
  colors = {
    primaryColor: '#1e40af',
    secondaryColor: '#3b82f6',
    accentColor: '#f59e0b',
    backgroundColor: '#ffffff',
    textColor: '#1f2937',
    visualTheme: 'clean professional corporate photography'
  };
}

const webhook = $('Webhook').first().json.body;
const profile = $('Fetch Brand Profile').first().json;
const bgPrompt = webhook.bgPrompt || '';
const heading = webhook.copy?.heading || '';
const theme = colors.visualTheme || 'professional marketing photography';

const imagePrompt = bgPrompt.trim()
  ? bgPrompt.trim() + ' No text, no logos, no overlaid graphics. High resolution, photorealistic.'
  : `Professional marketing photography for "${heading}". Style: ${theme}. Clean composition, no text, no logos, no overlaid graphics. High resolution, photorealistic.`;

const requestBody = JSON.stringify({
  model: 'gpt-image-1.5',
  prompt: imagePrompt,
  size: '1536x1024',
  quality: 'high',
  n: 1
});

return [{ json: { colors, logoUrl: profile.logo_url || null, requestBody } }];

const imageResponse = $('Generate Image').first().json;
const meta = $('Build Image Request').first().json;

const b64 = imageResponse.data?.[0]?.b64_json;
if (!b64) throw new Error('No image data: ' + JSON.stringify(imageResponse));

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(b64, 'base64'),
  'banner_bg.png',
  'image/png'
);

return [{
  json: {
    colors: meta.colors,
    logoUrl: meta.logoUrl
  },
  binary: { data: binaryData }
}];

const item = $input.first();
const meta = item.json;
const mime = (item.binary && item.binary.data && item.binary.data.mimeType) || 'image/png';
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const fileName = (meta.storagePath || meta.fileName || ('upload-' + Date.now() + '.png')).toString().split('/').pop();
const dataUrl = 'data:' + mime + ';base64,' + buffer.toString('base64');

const boundary = '----n8nIkBoundary' + Date.now().toString(36);
const parts = [];
function addField(name, value) {
  parts.push(
    '--' + boundary + '\r\n' +
    'Content-Disposition: form-data; name="' + name + '"\r\n\r\n' +
    value + '\r\n'
  );
}
addField('file', dataUrl);
addField('fileName', fileName);
addField('folder', '/generated-posts');
addField('useUniqueFileName', 'true');
parts.push('--' + boundary + '--\r\n');
const body = parts.join('');

let uploaded;
try {
  uploaded = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://upload.imagekit.io/api/v1/files/upload',
    headers: {
      Authorization: 'Basic __IMAGEKIT_BASIC_AUTH__',
      'Content-Type': 'multipart/form-data; boundary=' + boundary,
    },
    body,
    timeout: 120000,
  });
} catch (err) {
  throw new Error('ImageKit httpRequest failed: ' + (err.message || String(err)));
}

if (typeof uploaded === 'string') {
  try { uploaded = JSON.parse(uploaded); } catch (_) {}
}
if (!uploaded || !uploaded.url) {
  throw new Error('ImageKit upload failed: ' + JSON.stringify(uploaded));
}

return [{ json: Object.assign({}, meta, uploaded) }];

const upload = $('Upload to ImageKit').first().json;
const meta = $('Extract Image').first().json;
if (!upload.url) throw new Error('ImageKit upload failed: ' + JSON.stringify(upload));
return [{ json: {
  colors: meta.colors,
  logoUrl: meta.logoUrl,
  bgImageUrl: upload.url
} }];
